<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class AdmissionExamController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->canDo('students.manage'),403);}
 public function index(Request $r){$this->ok($r);$exams=DB::table('admission_exams as e')->join('admission_campaigns as c','c.id','=','e.campaign_id')->leftJoin('admission_targets as t','t.id','=','e.target_id')->leftJoin('specialties as sp','sp.id','=','t.specialty_id')->select('e.*','c.name as campaign_name','sp.code','sp.name as specialty')->orderBy('e.scheduled_at')->get();$campaigns=DB::table('admission_campaigns')->orderByDesc('starts_on')->get();$targets=DB::table('admission_targets as t')->join('specialties as sp','sp.id','=','t.specialty_id')->select('t.*','sp.code','sp.name as specialty')->get();return view('admission.exams',compact('exams','campaigns','targets'));}
 public function store(Request $r){$this->ok($r);$d=$r->validate(['campaign_id'=>'required|exists:admission_campaigns,id','target_id'=>'nullable|exists:admission_targets,id','name'=>'required|string|max:255','max_score'=>'required|numeric|min:1','min_score'=>'required|numeric|min:0','scheduled_at'=>'nullable|date','room'=>'nullable|string|max:100']);abort_if($d['min_score']>$d['max_score'],422,'Минимальный балл не может превышать максимальный.');DB::table('admission_exams')->insert($d+['status'=>'planned','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Вступительное испытание создано.');}
 public function show(Request $r,$id){$this->ok($r);$e=DB::table('admission_exams')->find($id);abort_if(!$e,404);$apps=DB::table('admission_applications as ap')->join('admission_applicants as a','a.id','=','ap.applicant_id')->where('ap.campaign_id',$e->campaign_id)->when($e->target_id,fn($q)=>$q->where('ap.target_id',$e->target_id))->select('ap.id as application_id','a.last_name','a.first_name','a.middle_name')->orderBy('a.last_name')->get();foreach($apps as $a)$a->result=DB::table('admission_exam_results')->where(['exam_id'=>$id,'application_id'=>$a->application_id])->first();return view('admission.exam-show',compact('e','apps'));}
 public function result(Request $r,$id){$this->ok($r);$e=DB::table('admission_exams')->find($id);abort_if(!$e,404);$d=$r->validate(['application_id'=>'required|exists:admission_applications,id','status'=>'required|in:admitted,passed,failed,absent','score'=>'nullable|numeric|min:0|max:'.$e->max_score,'note'=>'nullable|string|max:2000']);$app=DB::table('admission_applications')->find($d['application_id']);abort_if(!$app||$app->campaign_id!=$e->campaign_id||($e->target_id&&$app->target_id!=$e->target_id),422,'Заявление не относится к этому вступительному испытанию.');if(in_array($d['status'],['passed','failed'])&&$d['score']===null)abort(422,'Укажите балл.');if($d['score']!==null)$d['status']=$d['score']>=$e->min_score?'passed':'failed';DB::table('admission_exam_results')->updateOrInsert(['exam_id'=>$id,'application_id'=>$d['application_id']],$d+['recorded_by'=>$r->user()->id,'recorded_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$this->recalc($d['application_id']);return back()->with('success','Результат сохранён.');}
 private function recalc($application){$scores=DB::table('admission_exam_results')->where('application_id',$application)->where('status','passed')->pluck('score');DB::table('admission_applications')->where('id',$application)->update(['entrance_score'=>$scores->count()?round($scores->avg(),3):null,'updated_at'=>now()]);}
}